let mode='locked', key=null, salt=null, diskRaw=null, pending=Promise.resolve(), saving=0, saveError='', savedAt='', idleTimer, formBaseline='', authBusy=false, operationBusy=false, cancelPassword=null, recoveryRaw=null;
const LIMIT=5*1024*1024, ITERATIONS=310000;
const enc=new TextEncoder(),dec=new TextDecoder('utf-8',{fatal:true});
function validDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s&&s>='1900-01-01'&&s<='2200-12-31'}
function validateData(obj){
 if(!obj||typeof obj!=='object'||!Array.isArray(obj.students)||!Array.isArray(obj.observations)||!Array.isArray(obj.plans))throw Error('Struktur data tidak sesuai.');
 if(obj.students.length>2000||obj.observations.length>15000||obj.plans.length>10000)throw Error('Jumlah rekaman melebihi batas perangkat.');
 const text=(o,k,max,required=false)=>{const v=o[k];if(typeof v!=='string'||v.length>max||(required&&!v.trim())||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(v))throw Error('Data tidak valid pada '+k+'.');return v.trim()};
 const ids=new Set(),codes=new Set();const checkId=o=>{const id=text(o,'id',100,true);if(!/^[A-Za-z0-9-]+$/.test(id)||ids.has(id))throw Error('ID tidak valid atau ganda.');ids.add(id);return id};
 const students=obj.students.map(o=>{const id=checkId(o),code=text(o,'code',24,true).toUpperCase();if(!/^[A-Z0-9-]{3,24}$/.test(code)||codes.has(code))throw Error('Kode anak tidak valid atau ganda.');codes.add(code);return{id,code,klass:text(o,'klass',24,true),strength:text(o,'strength',500)}});
 const children=new Set(students.map(x=>x.id));
 const childId=o=>{const v=text(o,'childId',100,true);if(!children.has(v))throw Error('Catatan tidak memiliki profil anak.');return v};
 const date=(o,k)=>{const d=text(o,k,10,true);if(!validDate(d))throw Error('Tanggal tidak valid.');return d};
 const observations=obj.observations.map(o=>{const id=checkId(o),ch=childId(o),area=text(o,'area',2,true),indicator=text(o,'indicator',4,true);if(!Object.hasOwn(AREAS,area)||!Object.hasOwn(IND,indicator)||!indicator.startsWith(area)||typeof o.urgent!=='boolean')throw Error('Indikator atau penanda tidak valid.');const d=date(o,'date');if(d>iso())throw Error('Tanggal observasi di masa depan.');return{id,childId:ch,date:d,area,indicator,context:text(o,'context',180,true),prior:text(o,'prior',1500,true),behavior:text(o,'behavior',1500,true),impact:text(o,'impact',800),response:text(o,'response',1000),strength:text(o,'strength',900,true),occurrence:text(o,'occurrence',100),duration:text(o,'duration',80),author:text(o,'author',80,true),urgent:o.urgent}});
 const obs=new Map(observations.map(o=>[o.id,o]));
 const plans=obj.plans.map(o=>{const id=checkId(o),ch=childId(o),observationId=text(o,'observationId',100),status=text(o,'status',20,true),startDate=date(o,'startDate'),reviewDate=date(o,'reviewDate'),result=text(o,'result',1500);if(!Object.hasOwn(LABEL_STATUS,status)||reviewDate<startDate||(status==='done'&&!result)||(observationId&&obs.get(observationId)?.childId!==ch))throw Error('Rencana atau tautan observasi tidak valid.');return{id,childId:ch,observationId,status,startDate,reviewDate,result,action:text(o,'action',1500,true),owner:text(o,'owner',100,true)}});
 return {students,observations,plans};
}
function b64(bytes){let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str)}
function passwordDialog(title,confirmNew=false){return new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='password-overlay';overlay.innerHTML=`<section class="password-panel" role="dialog" aria-modal="true" aria-labelledby="password-title"><h2 id="password-title">${esc(title)}</h2><form id="password-dialog"><div class="field"><label for="dialog-password">Frasa sandi${confirmNew?' baru':''}</label><input id="dialog-password" type="password" name="password" required minlength="${confirmNew?12:1}" maxlength="256" autocomplete="${confirmNew?'new-password':'current-password'}"></div>${confirmNew?'<div class="field"><label for="dialog-confirm">Ulangi frasa sandi baru</label><input id="dialog-confirm" type="password" name="confirm" required minlength="12" maxlength="256" autocomplete="new-password"></div>':''}<p class="error" role="alert" id="password-error"></p><div class="form-footer"><button class="btn" type="button" id="password-cancel">Batal</button><button class="btn primary" type="submit">Lanjutkan</button></div></form></section>`;const focused=root.activeElement,body=root.querySelector('.app-body');if(body)body.inert=true;const done=value=>{overlay.remove();if(body)body.inert=false;cancelPassword=null;focused?.focus();resolve(value)};cancelPassword=()=>done(null);overlay.querySelector('#password-cancel').onclick=()=>done(null);overlay.querySelector('form').onsubmit=ev=>{ev.preventDefault();ev.stopPropagation();const f=ev.target;if(!f.reportValidity())return;const fd=new FormData(f),password=fd.get('password');if(confirmNew&&password!==fd.get('confirm')){overlay.querySelector('#password-error').textContent='Kedua frasa sandi harus sama.';return}f.reset();done(password)};overlay.addEventListener('keydown',ev=>{if(ev.key==='Escape'){ev.stopPropagation();done(null)}if(ev.key==='Tab'){const nodes=[...overlay.querySelectorAll('input,button')];const first=nodes[0],last=nodes.at(-1);if(ev.shiftKey&&root.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&root.activeElement===last){ev.preventDefault();first.focus()}}});root.appendChild(overlay);overlay.querySelector('input').focus()})}
function unb64(s){if(typeof s!=='string'||s.length>LIMIT*2||!/^[A-Za-z0-9+/]*={0,2}$/.test(s))throw Error('Format enkripsi tidak valid.');return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
function parseEnvelope(raw){if(typeof raw!=='string'||raw.length>LIMIT)throw Error('Ukuran cadangan melebihi 5 MB.');const o=JSON.parse(raw);if(o.format!=='EDUMIND-PSPA'||o.version!==1||o.kdf!=='PBKDF2-SHA256'||o.iterations!==ITERATIONS||o.cipher!=='AES-GCM'||unb64(o.salt).length!==16||unb64(o.iv).length!==12||unb64(o.data).length<16)throw Error('Format cadangan tidak didukung.');return o}
async function derive(password,saltBytes){const material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:saltBytes,iterations:ITERATIONS,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
