async function decryptData(raw,password){const env=parseEnvelope(raw),st=unb64(env.salt),k=await derive(password,st);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(env.iv),additionalData:enc.encode('EDUMIND-PSPA-v1')},k,unb64(env.data));return{data:validateData(JSON.parse(dec.decode(plain))),key:k,salt:st}}
async function writeDisk(raw,expected){const write=()=>{if(localStorage.getItem(STORAGE)!==expected)throw Error('Data berubah pada tab lain. Kunci dan buka ulang, atau unduh cadangan perubahan tab ini.');localStorage.setItem(STORAGE,raw);if(localStorage.getItem(STORAGE)!==raw)throw Error('Penyimpanan tidak dapat diverifikasi.');diskRaw=raw};if(navigator.locks)await navigator.locks.request(STORAGE,{mode:'exclusive'},write);else write()}
function updateStatus(){const el=root.getElementById('storage-state');if(!el)return;el.className='storage-state'+(saveError?' failed':'');el.textContent=mode==='demo'?'Latihan hanya di memori halaman; tidak mengubah data lokal terenkripsi.':saveError?'BELUM TERSIMPAN: '+saveError+' Unduh cadangan sebelum menutup halaman.':saving?'Mengenkripsi dan menyimpan perubahan…':savedAt?'Tersimpan terenkripsi di browser ini · '+savedAt:'Data lokal terbuka. Unduh cadangan setelah bekerja.'}
function save(){if(mode!=='live')return Promise.resolve(true);const snapshot=JSON.parse(JSON.stringify(data));saving++;updateStatus();pending=pending.then(async()=>{try{const raw=await encryptData(snapshot);await writeDisk(raw,diskRaw);saveError='';savedAt=new Date().toLocaleTimeString('id-ID');return true}catch(e){saveError=e.message||'Penyimpanan gagal.';return false}finally{saving--;updateStatus()}});return pending}
function selectFirst(){state={view:'home',student:data.students[0]?.id||'',reportStudent:data.students[0]?.id||'',obsFilter:'',studentFilter:'',signalsTab:'summary',editingObs:null,editingPlan:null,editingChild:null,mobile:false,safetyShown:false};formBaseline=''}
