async function lockApp(automatic=false){if(mode==='locked')return;if(operationBusy){touch();return}cancelPassword?.();if(!automatic&&!canLeave())return;await pending;if(saveError){try{recoveryRaw=await encryptData(data)}catch(e){touch();notify('Kunci ditunda karena cadangan belum dapat dibuat. '+e.message);return}} key=null;salt=null;data={students:[],observations:[],plans:[]};mode='locked';formBaseline='';clearTimeout(idleTimer);authView(automatic?'Aplikasi terkunci setelah 10 menit tanpa interaksi. Formulir yang belum disimpan tidak disimpan otomatis.':'Aplikasi dikunci.');}
