function authView(message=''){let hasVault=false,storageIssue='';try{hasVault=localStorage.getItem(STORAGE)!==null;const probe=STORAGE+'-probe';localStorage.setItem(probe,'1');localStorage.removeItem(probe)}catch(e){storageIssue='Penyimpanan browser tidak tersedia. Izinkan penyimpanan situs pada browser biasa.'}const supported=!!(window.isSecureContext&&crypto.subtle&&crypto.randomUUID);root.innerHTML='<style>'+APP_CSS+'</style>'+`<div class="app-body"><section class="auth"><div class="brand"><img class="brand-logo" src="${BRAND_LOGO}" alt="Edumind Academy"></div><h1>Pemetaan Sinyal Psikologis Anak</h1><p>${esc(DISCLAIMER)}</p><h2>${hasVault?'Buka data lokal':'Mulai data lokal terenkripsi'}</h2><p>${hasVault?'Masukkan frasa sandi untuk membuka data pada browser ini.':'Untuk satu petugas/perangkat. Buat frasa sandi sedikitnya 12 karakter; gunakan beberapa kata yang sulit ditebak. Data awal kosong.'}</p>${recoveryRaw?'<div class="persistent-urgent"><b>Ada perubahan yang belum tersimpan saat penguncian.</b><p>Unduh cadangan pemulihan sesi ini sebelum memuat ulang atau menutup tab. Pemulihan cadangan mengganti data di browser.</p>'+btn('Unduh cadangan pemulihan sesi','recovery-backup','btn primary')+'</div>':''}<form id="vault-form"><div class="field"><label for="vault-password">Frasa sandi</label><input id="vault-password" name="password" type="password" autocomplete="${hasVault?'current-password':'new-password'}" required minlength="${hasVault?1:12}" maxlength="256"></div>${hasVault?'':`<div class="field"><label for="vault-confirm">Ulangi frasa sandi</label><input id="vault-confirm" name="confirm" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></div><label class="choice"><input type="checkbox" name="consent" required> Saya berwenang mencatat, memakai kode samaran, menjaga perangkat/halaman ini, dan memahami bahwa data lokal memerlukan cadangan. Frasa sandi tidak dapat dipulihkan oleh Edumind.</label>`}<p id="auth-error" class="error" role="alert">${esc(storageIssue||(!supported?'Mode terenkripsi memerlukan browser modern dan HTTPS.':message))}</p><button class="btn primary" type="submit" ${storageIssue||!supported?'disabled':''}>${hasVault?'Buka data':'Buat penyimpanan'}</button></form><div class="form-footer">${btn('Coba latihan fiktif','start-demo','btn')}${btn('Pulihkan cadangan','auth-restore','btn')}</div><p class="tiny">Data tersimpan hanya di browser dan domain ini. Cadangan .edumind terenkripsi; laporan cetak/PDF tidak terenkripsi. Saat aplikasi terbuka, skrip lain pada domain yang sama dapat membaca data. Hindari perangkat bersama dan halaman dengan skrip yang tidak dipercaya.</p>${hasVault?btn('Hapus penyimpanan perangkat ini','erase-vault','btn danger small'):''}<p class="tiny">Versi ${VERSION} · Tanpa akun server atau sinkronisasi.</p><input type="file" id="restore-file" accept=".edumind,application/json" hidden></section></div><div id="toast" class="toast" role="status" hidden></div>`;root.getElementById('vault-password')?.focus()}
function setAuthError(msg){const el=root.getElementById('auth-error');if(el)el.textContent=msg;else notify(msg)}
async function openVault(ev){ev.preventDefault();if(authBusy)return;const f=ev.target;if(!f.reportValidity())return;if(recoveryRaw&&!confirmAction('Unduh cadangan pemulihan sesi dahulu. Buka data yang terakhir tersimpan? Cadangan pemulihan tetap tersedia saat aplikasi terkunci.'))return;const fd=new FormData(f),password=fd.get('password');let raw;try{raw=localStorage.getItem(STORAGE)}catch(e){setAuthError('Penyimpanan browser tidak tersedia.');return}if(!raw&&(password.length<12||password!==fd.get('confirm')||!fd.has('consent')))return setAuthError('Frasa sandi harus sama, minimal 12 karakter, dan persetujuan harus dicentang.');authBusy=true;const submit=f.querySelector('[type=submit]');submit.disabled=true;setAuthError('Membuka penyimpanan…');try{if(raw){const result=await decryptData(raw,password);data=result.data;key=result.key;salt=result.salt;diskRaw=raw}else{salt=crypto.getRandomValues(new Uint8Array(16));key=await derive(password,salt);data={students:[],observations:[],plans:[]};const fresh=await encryptData(data);await writeDisk(fresh,null)}f.reset();saveError='';savedAt='';mode='live';selectFirst();go('home');touch()}catch(e){key=null;salt=null;data={students:[],observations:[],plans:[]};setAuthError(raw?'Frasa sandi salah atau data tidak dapat dibaca. Data tersimpan tidak diubah.':'Gagal membuat penyimpanan: '+e.message)}finally{authBusy=false;if(submit.isConnected)submit.disabled=false}}
async function restoreFile(file){if(!file)return;if(file.size>LIMIT)return notify('Cadangan melebihi 5 MB.');if(!window.isSecureContext||!crypto.subtle)return notify('Pemulihan memerlukan HTTPS dan browser modern.');const password=await passwordDialog('Frasa sandi saat cadangan dibuat');if(password===null)return;try{const raw=await file.text();const result=await decryptData(raw,password);await pending;if(mode!=='locked'&&!canLeave())return;if(!confirmAction('Pemulihan mengganti SELURUH data lokal pada browser ini. Simpan cadangan data saat ini sebelum melanjutkan. Lanjutkan?'))return;const current=localStorage.getItem(STORAGE);if(mode==='live'&&current!==diskRaw)throw Error('Data berubah pada tab lain. Kunci dan buka ulang dahulu.');const canonical=await encryptData(result.data,result.key,result.salt);await writeDisk(canonical,current);data=result.data;key=result.key;salt=result.salt;mode='live';saveError='';savedAt='Dipulihkan';selectFirst();go('home');touch();notify('Cadangan dipulihkan. Frasa sandi mengikuti cadangan yang dipulihkan.')}catch(e){notify('Pemulihan gagal: frasa sandi salah, data rusak/tidak sesuai, atau penyimpanan gagal. Data sebelumnya tetap dipertahankan.')}}
async function changePassword(){await pending;if(saveError)return notify('Selesaikan kegagalan simpan atau unduh cadangan dahulu.');const current=await passwordDialog('Konfirmasi frasa sandi saat ini');if(current===null)return;try{await decryptData(diskRaw,current)}catch(e){return notify('Frasa sandi saat ini tidak sesuai.')}const password=await passwordDialog('Buat frasa sandi baru',true);if(password===null)return;if(password.length<12||password.length>256)return notify('Frasa sandi baru harus 12–256 karakter.');try{const st=crypto.getRandomValues(new Uint8Array(16)),k=await derive(password,st),raw=await encryptData(data,k,st);await writeDisk(raw,diskRaw);key=k;salt=st;savedAt='Frasa sandi diperbarui';updateStatus();notify('Frasa sandi diperbarui. Buat cadangan baru. Cadangan lama tetap memerlukan frasa sandi lama.')}catch(e){notify('Perubahan gagal: '+e.message)}}
function printReport(){const report=root.getElementById('report-paper');if(!report)return;const frame=document.createElement('iframe');frame.title='Cetak laporan observasi';frame.style.cssText='position:fixed;left:-10000px;top:0;width:900px;height:1px';document.body.appendChild(frame);const doc=frame.contentDocument;doc.open();doc.write('<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Laporan Observasi Pendidikan</title><style>body{font:11pt/1.5 Arial;color:#000}h3{margin:18px 0 8px}table{width:100%;border-collapse:collapse;font-size:9pt}td,th{border:1px solid #bbb;padding:7px;vertical-align:top;overflow-wrap:anywhere}th{text-align:left;background:#eee}thead{display:table-header-group}td:first-child{white-space:nowrap}p{white-space:pre-wrap}.report-title{font-size:19pt;font-weight:bold}.report-grid{display:flex;gap:25px;margin:15px 0}.report-grid b{display:block}.tiny{font-size:9pt}.report-legal{margin-top:18px;padding:10px;border:1px solid #777}tr{break-inside:avoid}@page{size:A4;margin:14mm}</style></head><body>'+report.outerHTML+'</body></html>');doc.close();frame.contentWindow.addEventListener('afterprint',()=>frame.remove(),{once:true});frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),120000)}
root.addEventListener('click',async ev=>{touch();const el=ev.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(authBusy||operationBusy)return;if(action==='recovery-backup'){download(recoveryRaw,'EDUMIND_PSPA_PEMULIHAN_SESI_'+iso()+'.edumind');return}if(action==='start-demo'){data=demo();mode='demo';selectFirst();go('home');return}if(action==='lock'){await lockApp();return}if(action==='backup'){await exclusive(backup);return}if(action==='change-password'){await exclusive(changePassword);return}if(action==='restore'||action==='auth-restore'){let input=root.getElementById('restore-file');if(!input){input=document.createElement('input');input.id='restore-file';input.type='file';input.accept='.edumind,application/json';input.hidden=true;root.appendChild(input)}input.value='';input.click();return}if(action==='erase-vault'){if(window.prompt('Ini menghapus data terenkripsi pada browser ini. Ketik HAPUS untuk melanjutkan:')!=='HAPUS')return;try{localStorage.removeItem(STORAGE);authView('Penyimpanan perangkat dihapus. Cadangan yang sudah diunduh tetap ada.')}catch(e){notify('Penyimpanan tidak dapat dihapus.')}return}if(mode!=='locked')onAction(ev)});
